package org.freecad.mobilelab;
import java.io.*;import org.json.*;
public final class HoleRepairRegression {
 static int checks;interface Action{void run()throws Exception;}static void check(boolean b,String s){if(!b)throw new AssertionError(s);checks++;}static void reject(Action a)throws Exception{try{a.run();}catch(Exception e){checks++;return;}throw new AssertionError("Unsafe hole accepted");}
 static void openTop(File input,File output,double z)throws Exception{java.util.ArrayList<float[]> kept=new java.util.ArrayList<>();try(RandomAccessFile f=new RandomAccessFile(input,"r")){int n=MeshFormats.count(f,100000);for(int i=0;i<n;i++){float[] p=MeshFormats.triangle(f,i);if(Math.abs(p[2]-z)>1e-6||Math.abs(p[5]-z)>1e-6||Math.abs(p[8]-z)>1e-6)kept.add(p);}}try(DataOutputStream out=new DataOutputStream(new FileOutputStream(output))){MeshFormats.stlHeader(out,kept.size());for(float[] p:kept)MeshFormats.stlTriangle(out,p);}}
 public static void main(String[] args)throws Exception{File root=new File(args.length>0?args[0]:"format-fixtures");root.mkdirs();NativeCad.clear();ProjectStore.reset();int box=NativeCad.create("Box",new double[]{20,10,4});File closed=new File(root,"closed.stl"),open=new File(root,"open.stl"),filled=new File(root,"filled.stl");NativeCad.write(closed.getAbsolutePath(),"stl",box);openTop(closed,open,4);check(PlanarMeshRepair.fill(open,filled,.00001)==1,"Cube boundary loop count");int mesh=NativeCad.read(filled.getAbsolutePath(),"stl");JSONObject report=new JSONObject(NativeCad.analyze(mesh,3));check(report.getBoolean("watertightMesh"),"Filled cube not closed");check(Math.abs(report.getDouble("volume")-800)<1e-5,"Cap winding/volume incorrect");reject(()->PlanarMeshRepair.fill(closed,filled,.00001));reject(()->PlanarMeshRepair.fill(open,filled,0));
 int profile=NativeCad.curve("Polyline",new double[]{0,0,0,1,3,0,0,1,3,1,0,1,1,1,0,1,1,3,0,1,0,3,0,1},true,0);int pad=NativeCad.model("Extrude solid",new int[]{profile},new double[]{0,0,2});File concave=new File(root,"concave.stl"),concaveOpen=new File(root,"concave-open.stl"),concaveFixed=new File(root,"concave-filled.stl");NativeCad.write(concave.getAbsolutePath(),"stl",pad);openTop(concave,concaveOpen,2);check(PlanarMeshRepair.fill(concaveOpen,concaveFixed,.00001)==1,"Concave boundary count");mesh=NativeCad.read(concaveFixed.getAbsolutePath(),"stl");report=new JSONObject(NativeCad.analyze(mesh,3));check(report.getBoolean("watertightMesh"),"Concave cap not closed");check(Math.abs(report.getDouble("volume")-10)<1e-5,"Concave ear-clipping filled outside boundary");java.util.ArrayList<float[]> warped=new java.util.ArrayList<>();warped.add(new float[]{0,0,0});warped.add(new float[]{1,0,0});warped.add(new float[]{1,1,1});warped.add(new float[]{0,1,0});reject(()->PlanarMeshRepair.cap(new java.util.ArrayList<>(java.util.Arrays.asList(0,1,2,3)),warped,.00001));System.out.println("PASS: "+checks+" mesh repair assertions: convex/concave planar caps, closed edge incidence, oriented volume and nonplanar/closed/invalid-tolerance rejection");}
}
